from collections import Counter

def transform(grid):
    """Fill the gaps between same-colored markers along each row with 2."""
    if not grid:
        return []
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        by_color = {}
        for c, value in enumerate(row):
            if value != bg:
                by_color.setdefault(value, []).append(c)
        for cols in by_color.values():
            if len(cols) >= 2:
                for c in range(cols[0] + 1, cols[-1]):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
